'use client';

import { type ReactNode, useEffect, useMemo, useState } from 'react';
import { Activity, AlertTriangle, ArrowUpRight, BadgeCheck, Boxes, ClipboardCheck, Database, Download, FileSearch, Gauge, GitBranch, LayoutDashboard, PackageCheck, ReceiptText, Search, ShieldCheck, SlidersHorizontal, Sparkles, TrendingUp, WalletCards } from 'lucide-react';

type Status = '可提交' | '已核验' | '待确认' | '待处理' | '规划中' | '未验证' | '当前有效' | '已失效';
type ActivityRow = { id: string; dealer: string; platform: string; activity: string; kind: '金额权益' | '赠品权益'; result: string; detail: string; status: Status; batch: string; rule: string; reportHref?: string };
type FeeTpmActivityRow = { activityId: number; activityNo: string; activityName: string; dealer: string; platform: string; promotionType: string; benefitKind: 'money' | 'gift'; startTime: string | null; endTime: string | null; importBatchId: number; calcBatchId: number; calcDate: string; releaseCutoff: string; actualDiscountTotal: number | null; settleAmount: number | null; participatingOrders: number; releasedOrders: number; releasedAmount: number; pendingOrders: number; pendingAmount: number; warningCount: number; tipCount: number; status: Status };
type FeeTpmCouponRow = { couponConfigId: number; configNo: string; couponName: string; couponType: string | null; dealer: string; platform: string; importBatchId: number; calcBatchId: number; calcDate: string; releaseCutoff: string; participatingOrders: number; couponBenefit: number; releasedCouponBenefit: number; status: Status; benefitKind: 'coupon' };
type FeeTpmIssueRow = { issueId: number; orderNo: string | null; issueType: string; level: '警告' | '提示'; reason: string; evidence: string | null; calcBatchId: number; activityId: number | null };
type FeeTpmSettlementRow = FeeTpmActivityRow;
type FeeTpmRoiRow = { kind: 'money' | 'gift' | 'coupon'; name: string; dealer: string; platform: string; periodStart: string | null; periodEnd: string | null; periodMissing: boolean; completedOrders: number | null; cokeQtyBase: number | null; cokePaidAmount: number | null; feeAmount: number | null; roi: number | null; calcBatchId: number };
type FeeTpmRun = { calcBatchId: number; importBatchId: number; dealer: string; platform: string; coverageStart: string | null; coverageEnd: string | null; calcDate: string; releaseCutoff: string };
type FeeTpmOverview = { submittableAmount: number; couponBenefit: number; releasedCouponBenefit: number; theoreticalActivityBenefit?: number; theoreticalCouponBenefit?: number; consistentOrders?: number; participatingOrders: number; releasedOrders: number; giftReleasedOrders: number; waitingCount: number; handlingCount: number; runs?: FeeTpmRun[] };
type FeeTpmData = { overview: FeeTpmOverview; activities: FeeTpmActivityRow[]; coupons: FeeTpmCouponRow[]; issues: FeeTpmIssueRow[]; settlements: FeeTpmSettlementRow[]; roi: FeeTpmRoiRow[] };
type BusinessRow = Record<string, string | number | null>;
type BusinessResponse = { rows: BusinessRow[]; total: number; limit: number; offset: number };
type OrderDetail = BusinessRow & { lines?: BusinessRow[]; activity_executions?: BusinessRow[]; coupon_redemptions?: BusinessRow[]; release?: BusinessRow | null; entitlement?: BusinessRow | null };
type ImportBatchRow = { import_batch_id: number; dealer_name: string; platform_name: string; coverage_start: string | null; coverage_end: string | null; imported_at: string; status: string; is_current: number; calc_date: string | null; order_count: number; participating_orders: number | null; released_orders: number | null; activity_benefit: number | null; coupon_benefit: number | null; released_activity_benefit: number | null; released_coupon_benefit: number | null };

const navGroups = [
  { label: '数据底座', items: [{ label: '数据接入', icon: Database }, { label: '主数据与映射', icon: GitBranch }, { label: '数据质量', icon: ShieldCheck }, { label: '业务数据', icon: Boxes }] },
  { label: '费用与促销 TPM', items: [{ label: '运营总览', icon: LayoutDashboard }, { label: '活动中心', icon: Activity }, { label: '权益核算', icon: ReceiptText }, { label: 'ROI 分析', icon: TrendingUp }, { label: '证据与异常', icon: FileSearch }, { label: '核销与对账', icon: ClipboardCheck }, { label: '结算批次', icon: WalletCards }] },
  { label: '增长运营', items: [{ label: 'KPI 考核', icon: Gauge }, { label: '分销管理', icon: Boxes }] },
];

const planning = [
  ['活动执行率', '已完成活动订单 ÷ 活动目标订单', '活动任务、订单状态、目标任务', '缺目标任务'],
  ['权益差异率', '理论权益与实际权益差异订单 ÷ 命中订单', 'result_entitlement、规则版本', '可复用现有结果'],
  ['异常关闭时效', '异常从创建到业务确认的时间', '问题台账、确认记录、角色', '缺协同记录'],
  ['活跃客户数', '期间内产生有效交易的标准客户数', '客户、订单、活动期间', '可从 CORE 计算'],
];
const businessObjects = [
  { key: 'orders', label: '订单', columns: [['order_no', '订单号'], ['order_time', '下单时间'], ['customer', '客户'], ['customer_no', '客户编号'], ['salesperson', '业务员'], ['order_status', '订单状态'], ['line_count', '商品行数'], ['paid_amount', '实付金额'], ['discount_amount', '订单优惠(全部)'], ['activities', '可乐活动(核销)'], ['coupons', '优惠券(核销)']] },
  { key: 'order-lines', label: '订单明细', columns: [['order_no', '订单号'], ['order_time', '下单时间'], ['customer', '客户'], ['product_no', '商品编号'], ['product', '商品'], ['spec', '规格'], ['quantity', '数量'], ['unit', '单位'], ['unit_price', '单价'], ['pre_discount_amount', '折前金额'], ['discount_amount', '优惠金额'], ['paid_amount', '实付金额'], ['activity_numbers', '活动编号'], ['coupon_numbers', '优惠券编号']] },
  { key: 'activity-executions', label: '活动核销明细', columns: [['order_no', '订单号'], ['order_time', '下单时间'], ['order_status', '订单状态'], ['activity_name', '活动名称'], ['activity_type', '活动类型'], ['customer_name', '客户'], ['salesperson', '业务员'], ['product_amount', '活动商品金额'], ['discount_amount', '活动优惠']] },
  { key: 'coupon-redemptions', label: '优惠券核销明细', columns: [['coupon_no', '券编号'], ['order_no', '订单号'], ['customer_name', '客户'], ['status', '券状态'], ['used_at', '使用时间'], ['discount_amount', '券优惠']] },
  { key: 'activities', label: '活动', columns: [['activity_no', '活动编号'], ['activity_name', '活动名称'], ['activity_type', '活动类型'], ['dealer', '经销商'], ['platform', '平台'], ['start_time', '开始时间'], ['end_time', '结束时间'], ['execution_count', '核销订单数'], ['discount_total', '核销优惠合计']] },
  { key: 'customers', label: '客户', columns: [['customer_no', '客户编号'], ['customer_name', '客户名称'], ['customer_type', '客户类型'], ['customer_region', '区域'], ['salesperson', '业务员'], ['phone', '电话'], ['added_at', '添加时间']] },
  { key: 'products', label: '商品', columns: [['product_no', '商品编号'], ['product_name', '商品名称'], ['brand', '品牌'], ['category', '品类'], ['spec', '规格'], ['base_unit', '基本单位'], ['box_conversion', '箱规']] },
  { key: 'fulfillments', label: '履约记录', columns: [['order_no', '订单号'], ['downstream_order_no', '下游订单号'], ['fulfillment_status', '履约状态'], ['outbound_at', '出库时间'], ['completed_at', '完成时间'], ['settlement_status', '结算状态'], ['return_qty', '退货数量']] },
] as const;
const money = (value: number | string | null | undefined) => `¥ ${Number(value ?? 0).toFixed(2)}`;
/** 默认走当前页面同源 `/api`（由 vite 转发到 python API），这样 Cursor 预览和局域网都能看到数据。仅在显式设置时才直连 8787。 */
const ec101Api = () => (process.env.NEXT_PUBLIC_EC101_API_URL ?? '').replace(/\/$/, '');
const reportHref = (kind: 'activity' | 'coupon', id: number, calcBatchId: number) => `${ec101Api()}/api/fee-tpm/${kind === 'activity' ? 'activities' : 'coupons'}/${id}/verification-report?calc_batch_id=${calcBatchId}`;
const statusStyles: Record<Status, string> = { 可提交: 'bg-emerald-50 text-emerald-700 ring-emerald-600/20', 已核验: 'bg-sky-50 text-sky-700 ring-sky-600/20', 待确认: 'bg-amber-50 text-amber-700 ring-amber-600/20', 待处理: 'bg-rose-50 text-rose-700 ring-rose-600/20', 规划中: 'bg-violet-50 text-violet-700 ring-violet-600/20', 未验证: 'bg-slate-100 text-slate-600 ring-slate-500/20', 当前有效: 'bg-emerald-50 text-emerald-700 ring-emerald-600/20', 已失效: 'bg-slate-100 text-slate-500 ring-slate-400/20' };

function useFeeTpmData(dealer: string, reloadKey: number) {
  const [data, setData] = useState<FeeTpmData | null>(null); const [error, setError] = useState(''); const [loading, setLoading] = useState(true);
  const base = ec101Api();
  useEffect(() => { const controller = new AbortController(); const params = new URLSearchParams(); if (dealer !== '全部经销商') params.set('dealer', dealer); const get = <T,>(path: string) => fetch(`${base}${path}?${params}`, { signal: controller.signal }).then((response) => { if (!response.ok) throw new Error(String(response.status)); return response.json() as Promise<T>; }); Promise.all([get<FeeTpmOverview>('/api/fee-tpm/overview'), get<{ rows: FeeTpmActivityRow[] }>('/api/fee-tpm/activities'), get<{ rows: FeeTpmCouponRow[] }>('/api/fee-tpm/coupons'), get<{ rows: FeeTpmRoiRow[] }>('/api/fee-tpm/roi'), get<{ rows: FeeTpmIssueRow[] }>('/api/fee-tpm/issues'), get<{ rows: FeeTpmSettlementRow[] }>('/api/fee-tpm/settlements')]).then(([overview, activities, coupons, roi, issues, settlements]) => { setData({ overview, activities: activities.rows, coupons: coupons.rows, roi: roi.rows, issues: issues.rows, settlements: settlements.rows }); setError(''); }).catch((reason: Error) => { if (reason.name !== 'AbortError') { setData(null); setError('无法连接核算服务。请在仓库根目录另开终端运行 python3 api/server.py，前端用 npm run dev 打开同一台机器上的页面；数据和页面必须在同一环境。'); } }).finally(() => setLoading(false)); return () => controller.abort(); }, [base, dealer, reloadKey]);
  return { data, error, loading };
}

function useImportBatches(reloadKey: number) {
  const [rows, setRows] = useState<ImportBatchRow[]>([]);
  const base = ec101Api();
  useEffect(() => { const controller = new AbortController(); fetch(`${base}/api/imports`, { signal: controller.signal }).then((response) => { if (!response.ok) throw new Error(String(response.status)); return response.json() as Promise<{ rows: ImportBatchRow[] }>; }).then((payload) => setRows(payload.rows ?? [])).catch(() => setRows([])); return () => controller.abort(); }, [base, reloadKey]);
  const dealers = useMemo(() => Array.from(new Set(rows.map((row) => row.dealer_name))), [rows]);
  return { rows, dealers };
}

function asActivityRow(row: FeeTpmActivityRow): ActivityRow { const isGift = row.benefitKind === 'gift'; return { id: String(row.activityId), dealer: row.dealer, platform: row.platform, activity: row.activityName, kind: isGift ? '赠品权益' : '金额权益', result: isGift ? `${row.releasedOrders} 单可释放` : money(row.settleAmount ?? row.releasedAmount), detail: isGift ? `参与 ${row.participatingOrders} 单 · 待释放 ${row.pendingOrders} 单 · 赠品按数量统计，不折算金额` : `核销 ${money(row.actualDiscountTotal)} · 可释放 ${row.releasedOrders}/${row.participatingOrders} 单 · 待释放 ${money(row.pendingAmount)}`, status: row.status, batch: `核算 ${row.calcBatchId} · 核算日 ${row.calcDate}`, rule: `${row.promotionType} · 核销计费，规则只核对`, reportHref: reportHref('activity', row.activityId, row.calcBatchId) }; }
function asCouponRow(row: FeeTpmCouponRow): ActivityRow { return { id: `coupon-${row.couponConfigId}`, dealer: row.dealer, platform: row.platform, activity: row.couponName, kind: '金额权益', result: money(row.releasedCouponBenefit), detail: `券核销 ${money(row.couponBenefit)} · ${row.participatingOrders} 单 · 配置 ${row.configNo}`, status: row.status, batch: `核算 ${row.calcBatchId} · 核算日 ${row.calcDate}`, rule: '优惠券 · 核销计费，规则只核对', reportHref: reportHref('coupon', row.couponConfigId, row.calcBatchId) }; }
function ReportLink({ href }: { href?: string }) { return href ? <a className="inline-flex items-center gap-1 text-xs font-semibold text-[#0f766e]" href={href}>下载核验报告 <Download size={14} /></a> : null; }

export default function Home() {
  const [active, setActive] = useState('运营总览'); const [dealer, setDealer] = useState('全部经销商'); const [selected, setSelected] = useState<ActivityRow | null>(null); const [draft, setDraft] = useState(false); const [reloadKey, setReloadKey] = useState(0);
  const { data: feeData, error: feeError, loading: feeLoading } = useFeeTpmData(dealer, reloadKey);
  const { rows: imports, dealers } = useImportBatches(reloadKey);
  const visible = useMemo(() => [...(feeData?.activities ?? []).map(asActivityRow), ...(feeData?.coupons ?? []).map(asCouponRow)], [feeData]);
  const group = navGroups.find((item) => item.items.some((nav) => nav.label === active))?.label ?? '费用与促销 TPM';
  const feeWorkspace = ['运营总览', '活动中心', '权益核算', 'ROI 分析', '证据与异常', '核销与对账', '结算批次'].includes(active);
  return <main className="min-h-screen bg-[#f5f7fb] text-slate-900"><div className="mx-auto flex min-h-screen max-w-[1560px]"><Sidebar active={active} onSelect={setActive} batches={imports.filter((row) => row.is_current).length} /><section className="min-w-0 flex-1"><header className="flex min-h-[78px] items-center justify-between border-b border-slate-200 bg-white px-5 sm:px-8"><div><p className="text-xs font-medium text-slate-500">{group} / {active}</p><h1 className="mt-1 text-xl font-semibold tracking-tight text-slate-950">EC101 费用运营台</h1></div><div className="flex items-center gap-3"><div className="hidden items-center gap-2 rounded-full bg-emerald-50 px-3 py-2 text-xs text-emerald-700 sm:flex"><BadgeCheck size={15} /> 标准库 · 按核销核算</div><div className="grid h-9 w-9 place-items-center rounded-full bg-[#dbeeea] text-sm font-semibold text-[#167e6d]">J</div></div></header><div className="mx-auto max-w-[1320px] px-5 py-7 sm:px-8"><Hero active={active} onDraft={() => setDraft(true)} />{feeWorkspace && feeLoading ? <div className="rounded-xl border border-slate-200 bg-white p-8 text-center text-sm text-slate-500">正在读取核算结果…</div> : feeWorkspace && feeError ? <div className="rounded-xl border border-amber-200 bg-amber-50 p-5 text-sm text-amber-800">{feeError}</div> : <>{active === '运营总览' && <Overview setActive={setActive} data={feeData} />}{active === '数据接入' && <SourceWorkspace imports={imports} onImported={() => setReloadKey((key) => key + 1)} />}{active === '主数据与映射' && <MappingWorkspace />}{active === '数据质量' && <QualityWorkspace setActive={setActive} />}{active === '业务数据' && <BusinessDataWorkspace dealers={dealers} />}{active === '活动中心' && <ActivityWorkspace rows={visible} dealer={dealer} dealers={dealers} setDealer={setDealer} setSelected={setSelected} />}{active === '权益核算' && <EntitlementWorkspace rows={visible} dealer={dealer} dealers={dealers} setDealer={setDealer} setSelected={setSelected} />}{active === 'ROI 分析' && <RoiWorkspace rows={feeData?.roi ?? []} dealer={dealer} dealers={dealers} setDealer={setDealer} />}{active === '证据与异常' && <IssueWorkspace rows={feeData?.issues ?? []} />}{(active === '核销与对账' || active === '结算批次') && <SettlementWorkspace rows={feeData?.settlements ?? []} compact={active === '结算批次'} onDraft={() => setDraft(true)} />}{(active === 'KPI 考核' || active === '分销管理') && <PlanningWorkspace mode={active} />}</>}{selected && <EvidencePanel row={selected} close={() => setSelected(null)} />}{draft && <DraftPanel rows={feeData?.settlements ?? []} close={() => setDraft(false)} />}</div></section></div></main>;
}

function Sidebar({ active, onSelect, batches }: { active: string; onSelect: (value: string) => void; batches: number }) { return <aside className="hidden w-[248px] shrink-0 border-r border-slate-200 bg-[#0c2743] px-4 py-6 text-slate-200 lg:block"><div className="mb-9 flex items-center gap-3 px-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-[#34bfa3] font-semibold text-[#08243e]">E</div><div><p className="text-sm font-semibold tracking-wide text-white">EC101</p><p className="text-xs text-slate-400">费用运营平台</p></div></div>{navGroups.map((group) => <div className="mb-7" key={group.label}><p className="mb-3 px-3 text-[11px] font-medium tracking-[0.14em] text-slate-500">{group.label}</p><nav className="space-y-1" aria-label={group.label}>{group.items.map(({ label, icon: Icon }) => <button className={`flex w-full items-center justify-between rounded-xl px-3 py-2.5 text-left text-sm transition ${active === label ? 'bg-white/12 text-white shadow-sm' : 'text-slate-300 hover:bg-white/8 hover:text-white'}`} key={label} onClick={() => onSelect(label)} type="button"><span className="flex items-center gap-3"><Icon size={17} strokeWidth={1.8} />{label}</span>{label === 'KPI 考核' || label === '分销管理' ? <span className="rounded-full bg-violet-400/15 px-1.5 py-0.5 text-[10px] text-violet-200">规划</span> : null}</button>)}</nav></div>)}<div className="border-t border-white/10 px-3 pt-5 text-xs leading-5 text-slate-500">标准导入库<br />当前有效批次 {batches} 个</div></aside>; }
function Hero({ active, onDraft }: { active: string; onDraft: () => void }) { return <section className="mb-7 flex flex-col justify-between gap-4 rounded-2xl border border-[#cfe3e6] bg-[linear-gradient(105deg,#effbfa_0%,#f7fbfd_55%,#ffffff_100%)] p-5 sm:flex-row sm:items-end"><div><p className="text-xs font-semibold tracking-[0.12em] text-[#328075]">TPM 费用运营台 · {active}</p><h2 className="mt-2 text-2xl font-semibold tracking-tight text-slate-900">把每笔费用，从活动规则追到结算证据。</h2><p className="mt-2 max-w-3xl text-sm leading-6 text-slate-600">基于标准数据、CORE 业务对象与核算批次呈现。金额、赠品数量、质量门禁和业务确认分开管理；原始文件仅作为归档证据保存。</p></div><button className="inline-flex shrink-0 items-center justify-center gap-2 rounded-xl bg-[#0f766e] px-4 py-2.5 text-sm font-medium text-white shadow-sm transition hover:bg-[#0b5f59]" onClick={onDraft} type="button">生成对账草稿 <ArrowUpRight size={16} /></button></section>; }
function Overview({ setActive, data }: { setActive: (value: string) => void; data: FeeTpmData | null }) { const overview = data?.overview; const runs = overview?.runs ?? []; return <><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="活动费用可释放" value={money(overview?.submittableAmount)} note="满减等金额活动，按核销明细、已完成且达 T-2" tone="emerald" /><Metric label="优惠券可释放" value={money(overview?.releasedCouponBenefit)} note={`券核销合计 ${money(overview?.couponBenefit)}`} tone="emerald" /><Metric label="参与订单" value={`${overview?.participatingOrders ?? 0} 单`} note={`可释放 ${overview?.releasedOrders ?? 0} 单 · 满赠可释放 ${overview?.giftReleasedOrders ?? 0} 单${overview?.theoreticalActivityBenefit ? ` · 理论 ${overview.theoreticalActivityBenefit} / 一致 ${overview.consistentOrders ?? 0}` : ''}`} tone="teal" /><Metric label="待处理 / 待确认" value={`${overview?.handlingCount ?? 0} / ${overview?.waitingCount ?? 0}`} note="警告阻止结算；待确认表示活动暂无可释放订单" tone="amber" /></section><section className="mt-7 grid gap-6 xl:grid-cols-[minmax(0,1.5fr)_360px]"><div className="rounded-2xl border border-slate-200 bg-white shadow-sm"><PanelHeader title="当前核算批次" subtitle="每个当前有效的导入批次取最新一次核算" action="查看权益核算" onClick={() => setActive('权益核算')} />{runs.length ? <div className="p-5"><Table headers={['经销商 / 平台', '数据期间', '核算日', '释放截止']} rows={runs.map((run) => [<div key={run.calcBatchId}><p className="font-medium text-slate-800">{run.dealer}</p><p className="mt-1 text-xs text-slate-500">{run.platform} · 导入批次 {run.importBatchId}</p></div>, `${run.coverageStart ?? '—'} 至 ${run.coverageEnd ?? '—'}`, run.calcDate, run.releaseCutoff])} /></div> : <p className="p-5 text-sm text-slate-500">还没有导入任何标准数据。请先到“数据接入”上传。</p>}</div><div className="rounded-2xl border border-slate-200 bg-white shadow-sm"><PanelHeader title="核算口径" subtitle="实时读取，不在浏览器重算" /><div className="space-y-3 px-5 pb-5"><Health label="费用来源" value="活动核销 + 券核销" good /><Health label="订单行优惠" value="仅展示，不计费" good /><Health label="可释放" value="已完成且 T-2" good /><Health label="满赠" value="按订单数" /></div></div></section><section className="mt-7 grid gap-4 md:grid-cols-3"><Feature title="活动 → 订单 → 费用" text="每一行结果都能回到活动核销明细、订单和核算批次。" /><Feature title="金额与实物分开" text="满减、优惠券展示人民币；满赠只统计参与和可释放订单数。" /><Feature title="无静态回退" text="API 不可用或结果为空时会明确提示，而不是显示旧快照。" /></section></>; }
type ImportCalculation = { calculation_run_id: number; calc_date: string; release_cutoff: string; activity_benefit: number; coupon_benefit: number; total_benefit: number; released_activity_benefit: number; released_coupon_benefit: number; participating_orders: number; released_orders: number; status: string };
type ImportActivitySummary = { activity_id: number; activity_no: string; activity_name: string; activity_type: string; actual_discount_total: number; participating_orders: number; released_orders: number; released_amount: number; pending_orders: number; pending_amount: number };
type ReleaseRow = { order_id: number; order_no: string; order_time: string | null; order_status: string; customer_no: string; customer_name: string | null; salesperson: string | null; is_candidate: number; reason: string; activity_benefit: number; coupon_benefit: number; activities: string | null; coupons: string | null };
type ReleaseResponse = { import_batch_id: number; calculation: ImportCalculation; rows: ReleaseRow[]; total: number; limit: number; offset: number };
type ImportResponse = { import_batch_id: number; calculation_run_id?: number; status?: string; calculation?: ImportCalculation; message?: string; error?: string };
type ImportDetail = { calculation?: ImportCalculation | null; activities?: ImportActivitySummary[] };

function releaseCsv(rows: ReleaseRow[]): string {
  const header = ['订单号', '下单时间', '客户编号', '客户名称', '业务员', '订单状态', '活动', '活动优惠', '优惠券', '券优惠', '是否可释放', '原因'];
  const escape = (value: string | number | null | undefined) => `"${String(value ?? '').replace(/"/g, '""')}"`;
  const lines = rows.map((row) => [row.order_no, row.order_time, row.customer_no, row.customer_name, row.salesperson, row.order_status, row.activities, row.activity_benefit, row.coupons, row.coupon_benefit, row.is_candidate ? '可释放' : '不可释放', row.reason].map(escape).join(','));
  return '\uFEFF' + [header.map(escape).join(','), ...lines].join('\n');
}

function SourceWorkspace({ imports, onImported }: { imports: ImportBatchRow[]; onImported: () => void }) {
  const apiBase = ec101Api();
  const [workbook, setWorkbook] = useState<File | null>(null); const [archive, setArchive] = useState<File | null>(null); const [calcDate, setCalcDate] = useState(''); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const [uploading, setUploading] = useState(false);
  const [batchId, setBatchId] = useState<number | null>(null); const [calculation, setCalculation] = useState<ImportCalculation | null>(null); const [activities, setActivities] = useState<ImportActivitySummary[]>([]);
  const [filter, setFilter] = useState<'all' | '1' | '0'>('all'); const [release, setRelease] = useState<ReleaseResponse | null>(null); const [releaseError, setReleaseError] = useState('');
  const loadBatch = async (id: number) => {
    const detail = (await fetch(`${apiBase}/api/imports/${id}`).then((res) => res.json())) as ImportDetail;
    setCalculation(detail.calculation ?? null); setActivities(detail.activities ?? []); setBatchId(id);
    return detail;
  };
  const importWorkbook = async () => {
    if (!workbook) { setError('请选择标准数据 Excel'); return; }
    setUploading(true); setMessage(''); setError(''); setBatchId(null); setRelease(null);
    try {
      const body = new FormData(); body.append('workbook', workbook); if (archive) body.append('sources', archive); if (calcDate) body.append('calc_date', calcDate);
      const response = await fetch(`${apiBase}/api/imports`, { method: 'POST', body }); const payload = (await response.json()) as ImportResponse;
      if (!response.ok) throw new Error(payload.message ?? payload.error ?? `HTTP ${response.status}`);
      const detail = await loadBatch(payload.import_batch_id);
      if (!detail.calculation && payload.calculation) setCalculation(payload.calculation);
      setMessage(`导入成功：批次 ${payload.import_batch_id}，核算日 ${payload.calculation?.calc_date ?? '今天'}`);
      onImported();
    } catch (reason) { setError(`导入失败：${reason instanceof Error ? reason.message : '请检查文件'}`); } finally { setUploading(false); }
  };
  useEffect(() => {
    if (batchId === null) return;
    const controller = new AbortController(); const params = new URLSearchParams({ limit: '2000' }); if (filter !== 'all') params.set('candidate', filter);
    fetch(`${apiBase}/api/imports/${batchId}/release?${params}`, { signal: controller.signal }).then((res) => { if (!res.ok) throw new Error(String(res.status)); return res.json() as Promise<ReleaseResponse>; }).then((payload) => { setRelease(payload); setReleaseError(''); }).catch((reason: Error) => { if (reason.name !== 'AbortError') { setRelease(null); setReleaseError('无法加载逐单释放清单'); } });
    return () => controller.abort();
  }, [apiBase, batchId, filter]);
  const downloadCsv = () => { if (!release) return; const blob = new Blob([releaseCsv(release.rows)], { type: 'text/csv;charset=utf-8' }); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `释放清单-批次${release.import_batch_id}-${filter === 'all' ? '全部' : filter === '1' ? '可释放' : '不可释放'}.csv`; anchor.click(); URL.revokeObjectURL(url); };
  return <Workspace title="数据接入" subtitle="业务人员上传转换工具生成的标准数据；系统保留 sources.zip 归档，并在导入后自动核算"><div className="mb-5 rounded-xl border border-teal-100 bg-teal-50/60 p-4"><p className="text-sm font-semibold text-teal-900">上传标准数据</p><p className="mt-1 text-xs leading-5 text-teal-800">先用 Windows 转换工具把快马 / 舟谱源文件转换为标准 Excel，再上传。原始文件请一并打包为 sources.zip 便于追溯。费用只按活动核销与优惠券核销统计；可释放 = 订单已完成且下单时间早于核算日前两天。</p><div className="mt-4 grid gap-3 md:grid-cols-[1fr_1fr_160px_auto] md:items-end"><label className="text-xs font-medium text-slate-700">标准数据 Excel<input aria-label="标准数据 Excel" accept=".xlsx,.xls" className="mt-1 block w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs" onChange={(event) => setWorkbook(event.target.files?.[0] ?? null)} type="file" /></label><label className="text-xs font-medium text-slate-700">原始文件归档（可选）<input aria-label="原始文件归档" accept=".zip" className="mt-1 block w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs" onChange={(event) => setArchive(event.target.files?.[0] ?? null)} type="file" /></label><label className="text-xs font-medium text-slate-700">核算日（默认今天）<input aria-label="核算日" className="mt-1 block w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs" onChange={(event) => setCalcDate(event.target.value)} type="date" value={calcDate} /></label><button className="rounded-lg bg-[#0f766e] px-4 py-2.5 text-xs font-semibold text-white disabled:opacity-50" disabled={uploading} onClick={importWorkbook} type="button">{uploading ? '导入中…' : '开始导入'}</button></div>{message && <p className="mt-3 text-xs font-medium text-emerald-700">{message}</p>}{error && <p className="mt-3 text-xs font-medium text-rose-700">{error}</p>}</div>
    {calculation && <div className="mb-5"><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="参与订单" value={`${calculation.participating_orders} 单`} note={`可释放 ${calculation.released_orders} 单 · 截止 ${calculation.release_cutoff}`} tone="teal" /><Metric label="活动优惠（核销）" value={money(calculation.activity_benefit)} note={`可释放 ${money(calculation.released_activity_benefit)}`} tone="emerald" /><Metric label="优惠券优惠（核销）" value={money(calculation.coupon_benefit)} note={`可释放 ${money(calculation.released_coupon_benefit)}`} tone="emerald" /><Metric label="待释放" value={`${calculation.participating_orders - calculation.released_orders} 单`} note="未完成或未达 T-2 的参与订单" tone="amber" /></section>
      {activities.length > 0 && <div className="mt-4"><Table headers={['活动', '类型', '参与订单', '核销优惠', '可释放订单', '可释放金额', '待释放订单', '待释放金额', '报告']} rows={activities.map((row) => [<span className="font-medium text-slate-800" key={row.activity_id}>{row.activity_name}</span>, row.activity_type, row.participating_orders, money(row.actual_discount_total), row.released_orders, money(row.released_amount), row.pending_orders, money(row.pending_amount), calculation ? <ReportLink href={reportHref('activity', row.activity_id, calculation.calculation_run_id)} key="report" /> : ''])} /></div>}
      <div className="mt-5 flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2 text-xs"><span className="font-medium text-slate-700">逐单释放清单</span>{(['all', '1', '0'] as const).map((key) => <button className={`rounded-full px-3 py-1 font-medium ring-1 ring-inset ${filter === key ? 'bg-[#0f766e] text-white ring-[#0f766e]' : 'bg-white text-slate-600 ring-slate-200'}`} key={key} onClick={() => setFilter(key)} type="button">{key === 'all' ? '全部' : key === '1' ? '可释放' : '不可释放'}</button>)}{release && <span className="text-slate-500">共 {release.total} 单</span>}</div><button className="inline-flex items-center gap-1 text-xs font-semibold text-[#0f766e] disabled:opacity-50" disabled={!release} onClick={downloadCsv} type="button"><Download size={14} /> 导出 CSV</button></div>
      {releaseError && <p className="mt-3 text-xs font-medium text-rose-700">{releaseError}</p>}
      {release && <div className="mt-3"><Table headers={['订单号', '下单时间', '客户', '订单状态', '活动 / 优惠券', '活动优惠', '券优惠', '释放']} rows={release.rows.map((row) => [<span className="font-mono text-xs text-slate-800" key={row.order_id}>{row.order_no}</span>, <span className="text-xs text-slate-600" key="time">{row.order_time ?? ''}</span>, <div key="customer"><p className="text-slate-800">{row.customer_name ?? row.customer_no}</p><p className="text-xs text-slate-500">{row.customer_no}</p></div>, row.order_status, <div className="text-xs" key="promo"><p>{row.activities ?? '—'}</p>{row.coupons && <p className="text-slate-500">券 {row.coupons}</p>}</div>, money(row.activity_benefit), money(row.coupon_benefit), <div key="release"><Status status={row.is_candidate ? '可提交' : '待确认'} /><p className="mt-1 text-xs text-slate-500">{row.reason}</p></div>])} /></div>}
    </div>}
    <div className="mb-3 flex items-center justify-between text-xs text-slate-500"><span className="font-medium text-slate-700">已导入批次</span><span>同一经销商、平台、数据期间重复上传时，旧批次自动失效；不同期间并存</span></div>
    {imports.length ? <Table headers={['经销商 / 平台', '批次', '数据期间', '订单数', '核算日', '参与 / 可释放', '活动优惠可释放', '券优惠可释放', '状态', '操作']} rows={imports.map((row) => [<div key={row.import_batch_id}><p className="font-medium text-slate-800">{row.dealer_name}</p><p className="mt-1 text-xs text-slate-500">{row.platform_name} · {row.imported_at.replace('T', ' ')}</p></div>, row.import_batch_id, `${row.coverage_start ?? '—'} 至 ${row.coverage_end ?? '—'}`, row.order_count, row.calc_date ?? '—', `${row.participating_orders ?? 0} / ${row.released_orders ?? 0}`, money(row.released_activity_benefit), money(row.released_coupon_benefit), <Status status={row.is_current ? '当前有效' : '已失效'} key="status" />, <button className="text-xs font-semibold text-[#0f766e]" key="view" onClick={() => { setMessage(''); setError(''); setRelease(null); void loadBatch(row.import_batch_id); }} type="button">查看结果</button>])} /> : <p className="rounded-xl border border-slate-200 p-6 text-center text-sm text-slate-500">还没有导入记录</p>}</Workspace>;
}
function MappingWorkspace() { return <Workspace title="主数据与映射" subtitle="转换器把快马、舟谱等平台字段统一成标准数据，CORE 保存稳定业务对象；映射不足不会被页面默认为 0"><div className="grid gap-4 md:grid-cols-3"><Mapping title="舟谱 V1 映射" value="166 行" detail="由桌面转换工具执行" tone="good" /><Mapping title="跨系统映射" value="待补齐" detail="平台适配规则可独立升级" tone="warn" /><Mapping title="编号约束" value="字符串" detail="订单号、券号、使用单号" tone="good" /></div><Info text="平台新增接入时只增加转换器与适配规则，不改变订单、活动、权益和费用的核心关系。" /></Workspace>; }
function QualityWorkspace({ setActive }: { setActive: (value: string) => void }) { return <Workspace title="数据质量" subtitle="质量结论直接影响是否可以生成结算候选"><div className="grid gap-4 md:grid-cols-3"><Quality title="通过" value="2 批" detail="快马与舟谱已核验" tone="good" /><Quality title="条件通过" value="2 批" detail="存在待确认事项" tone="warn" /><Quality title="阻断 / 未验证" value="1 批" detail="财经云数据窗口不完整" tone="bad" /></div><div className="mt-5 flex items-center justify-between rounded-xl border border-amber-100 bg-amber-50/60 p-4"><div><p className="text-sm font-semibold text-amber-900">财经云当前不能进入正式结算</p><p className="mt-1 text-xs leading-5 text-amber-800">缺少完整活动期订单、活动配置和支付/履约证据，需补数后重新运行验证器。</p></div><button className="text-xs font-semibold text-amber-800 underline" onClick={() => setActive('数据接入')} type="button">查看批次</button></div></Workspace>; }
function ActivityWorkspace({ rows, dealer, dealers, setDealer, setSelected }: { rows: ActivityRow[]; dealer: string; dealers: string[]; setDealer: (value: string) => void; setSelected: (row: ActivityRow) => void }) { return <Workspace title="活动中心" subtitle="活动来自快马活动明细中解析出的活动名称；费用只按活动核销明细统计"><Filter dealer={dealer} dealers={dealers} setDealer={setDealer} />{!rows.length && <p className="rounded-xl border border-slate-200 p-6 text-center text-sm text-slate-500">当前没有核算过的活动，请先在“数据接入”上传标准数据</p>}<div className="grid gap-4 md:grid-cols-2">{rows.map((row) => <article className="rounded-xl border border-slate-200 p-4 transition hover:border-teal-200 hover:shadow-sm" key={row.id}><div className="flex items-start justify-between gap-3"><div><p className="text-xs text-slate-500">{row.dealer} · {row.platform}</p><h3 className="mt-1 font-semibold text-slate-800">{row.activity}</h3></div><Status status={row.status} /></div><div className="mt-4 flex items-end justify-between gap-3"><div><p className="text-xs text-slate-500">{row.kind}</p><p className="mt-1 text-xl font-semibold text-slate-900">{row.result}</p></div><div className="flex flex-col items-end gap-2"><ReportLink href={row.reportHref} /><button className="inline-flex items-center gap-1 text-xs font-semibold text-[#0f766e]" onClick={() => setSelected(row)} type="button">打开详情 <ArrowUpRight size={14} /></button></div></div><p className="mt-3 border-t border-slate-100 pt-3 text-xs leading-5 text-slate-500">{row.detail}</p></article>)}</div></Workspace>; }
function EntitlementWorkspace({ rows, dealer, dealers, setDealer, setSelected }: { rows: ActivityRow[]; dealer: string; dealers: string[]; setDealer: (value: string) => void; setSelected: (row: ActivityRow) => void }) { return <Workspace title="权益核算" subtitle="订单 × 活动 × 核算批次；结果在导入时已算好并保存，页面不重新计算；逐单清单见“数据接入”"><Filter dealer={dealer} dealers={dealers} setDealer={setDealer} /><Table headers={['经销商 / 平台', '活动与权益类型', '结果', '口径与批次', '状态', '报告', '证据']} rows={rows.map((row) => [<div key={row.id}><p className="font-medium text-slate-800">{row.dealer}</p><p className="mt-1 text-xs text-slate-500">{row.platform}</p></div>, <div key="activity"><p className="font-medium text-slate-700">{row.activity}</p><p className="mt-1 text-xs text-slate-500">{row.kind}</p></div>, <div key="result"><p className="font-semibold text-slate-900">{row.result}</p><p className="mt-1 text-xs text-slate-500">{row.detail}</p></div>, <div key="rule"><p className="text-xs text-slate-700">{row.rule}</p><p className="mt-1 text-[11px] text-slate-400">{row.batch}</p></div>, <Status status={row.status} key="status" />, <ReportLink href={row.reportHref} key="report" />, <button className="inline-flex items-center gap-1 text-xs font-semibold text-[#0f766e]" onClick={() => setSelected(row)} type="button" key="evidence">查看证据 <ArrowUpRight size={14} /></button>])} /></Workspace>; }
const roiKind = (kind: FeeTpmRoiRow['kind']) => (kind === 'gift' ? '满赠' : kind === 'coupon' ? '优惠券' : '满减/金额');
function RoiWorkspace({ rows, dealer, dealers, setDealer }: { rows: FeeTpmRoiRow[]; dealer: string; dealers: string[]; setDealer: (value: string) => void }) { const href = `${ec101Api()}/api/fee-tpm/roi.xlsx${dealer === '全部经销商' ? '' : `?dealer=${encodeURIComponent(dealer)}`}`; return <Workspace title="ROI 分析" subtitle="核销已完成单 × 品牌可口可乐 × 实付金额；销量把箱/件换成瓶或罐；满赠只出金额，不算 ROI"><Filter action={<a aria-label="下载销量费用表" className="inline-flex items-center gap-1 text-xs font-semibold text-[#0f766e]" href={href}>下载销量费用表 <Download size={14} /></a>} dealer={dealer} dealers={dealers} setDealer={setDealer} />{!rows.length && <p className="rounded-xl border border-slate-200 p-6 text-center text-sm text-slate-500">当前没有可分析的活动或优惠券</p>}{rows.length > 0 && <Table headers={['活动 / 券', '类型', '上线期间', '已完成参与', '可乐销量（瓶/罐）', '可乐实付', '核销费用', 'ROI']} rows={rows.map((row) => [<div key={row.name}><p className="font-medium text-slate-800">{row.name}</p><p className="mt-1 text-xs text-slate-500">{row.dealer} · {row.platform}</p></div>, roiKind(row.kind), row.periodMissing ? '期间缺失' : `${row.periodStart ?? ''} 至 ${row.periodEnd ?? ''}`, row.completedOrders ?? '—', row.cokeQtyBase == null ? '—' : row.cokeQtyBase, row.cokePaidAmount == null ? '—' : money(row.cokePaidAmount), row.feeAmount == null ? '—' : money(row.feeAmount), row.kind === 'gift' ? '满赠只统计金额' : row.roi == null ? '—' : `${row.roi}`])} />}</Workspace>; }
function IssueWorkspace({ rows }: { rows: FeeTpmIssueRow[] }) { return <Workspace title="证据与异常" subtitle="展示 RESULT 原始警告、提示与证据；第一期不伪造 P0/P1、负责人或关闭状态"><div className="space-y-3">{rows.map((issue) => <article className="flex flex-col gap-4 rounded-xl border border-slate-200 p-4 sm:flex-row sm:items-start sm:justify-between" key={issue.issueId}><div className="flex gap-3"><div className={`mt-0.5 grid h-8 w-8 shrink-0 place-items-center rounded-lg ${issue.level === '警告' ? 'bg-rose-50 text-rose-600' : 'bg-amber-50 text-amber-600'}`}><AlertTriangle size={17} /></div><div><div className="flex flex-wrap items-center gap-2"><h3 className="text-sm font-semibold text-slate-800">{issue.issueType}</h3><span className="text-[11px] font-semibold text-slate-400">{issue.level} · calc-{issue.calcBatchId}</span></div><p className="mt-1 max-w-2xl text-xs leading-5 text-slate-500">{issue.reason}</p><p className="mt-1 text-[11px] text-slate-400">订单：{issue.orderNo ?? '批次级问题'} · 证据：{issue.evidence ?? '—'}</p></div></div><div className="shrink-0 text-left sm:text-right"><p className="text-xs font-semibold text-slate-700">{issue.activityId === null ? '批次级异常' : `活动 ${issue.activityId}`}</p></div></article>)}{!rows.length && <p className="rounded-xl border border-slate-200 p-6 text-center text-sm text-slate-500">当前筛选没有质量问题</p>}</div></Workspace>; }
function SettlementWorkspace({ rows, onDraft, compact = false }: { rows: FeeTpmSettlementRow[]; onDraft: () => void; compact?: boolean }) { const shown = compact ? rows.slice(0, 2) : rows; const total = rows.reduce((sum, row) => sum + Number(row.settleAmount ?? 0), 0); return <Workspace title={compact ? '结算批次' : '核销与对账'} subtitle="只读展示可释放的金额活动；满赠、待确认和待处理活动不会进入结算草稿"><div className="mb-4 flex items-center justify-between rounded-xl border border-emerald-100 bg-emerald-50/60 p-4"><div><p className="text-sm font-semibold text-emerald-900">当前 {rows.length} 个金额活动可释放，合计 {money(total)}</p><p className="mt-1 text-xs text-emerald-800">满赠按订单数展示，不折算人民币。</p></div><button className="rounded-lg bg-[#0f766e] px-3 py-2 text-xs font-semibold text-white" onClick={onDraft} type="button">生成草稿</button></div><Table headers={['经销商', '结算范围', '可释放金额', '核算批次', '状态', '报告']} rows={shown.map((row) => [row.dealer, `${row.activityName} · ${row.releasedOrders}/${row.participatingOrders} 单可释放`, <span className="font-semibold text-slate-900" key="amount">{money(row.settleAmount)}</span>, `核算 ${row.calcBatchId} · 核算日 ${row.calcDate}`, <Status status={row.status} key="status" />, <ReportLink href={reportHref('activity', row.activityId, row.calcBatchId)} key="report" />])} /></Workspace>; }
function PlanningWorkspace({ mode }: { mode: string }) { const kpi = mode === 'KPI 考核'; return <Workspace title={`${mode} · 规划中`} subtitle="本期只建立产品入口和数据契约，不产生正式考核或分销结果"><div className="mb-5 flex items-start gap-3 rounded-xl border border-violet-100 bg-violet-50/60 p-4"><Sparkles className="mt-0.5 shrink-0 text-violet-600" size={18} /><div><p className="text-sm font-semibold text-violet-900">{kpi ? 'KPI 将复用费用与订单事实' : '分销将复用经销商、商品与流向事实'}</p><p className="mt-1 text-xs leading-5 text-violet-800">当前不展示虚构指标，先把依赖数据和口径放进产品架构。</p></div></div>{kpi ? <div className="grid gap-3 md:grid-cols-2">{planning.map((metric) => <article className="rounded-xl border border-slate-200 p-4" key={metric[0]}><div className="flex items-start justify-between gap-3"><h3 className="text-sm font-semibold text-slate-800">{metric[0]}</h3><Status status="规划中" /></div><p className="mt-2 text-xs text-slate-600">{metric[1]}</p><div className="mt-4 grid gap-2 text-[11px] text-slate-500"><p><span className="font-semibold text-slate-700">依赖：</span>{metric[2]}</p><p><span className="font-semibold text-slate-700">准备度：</span>{metric[3]}</p></div></article>)}</div> : <div className="grid gap-4 md:grid-cols-2"><Mapping title="经销商与区域" value="待接入" detail="复用 dealer_platform、customer 和区域主数据" tone="neutral" /><Mapping title="商品与库存" value="预留" detail="复用 product，补充深度库存与库存快照" tone="neutral" /><Mapping title="Sell-in" value="预留" detail="经销商拿货/进货表，月 × 合作伙伴 × 商品" tone="warn" /><Mapping title="Sell-out" value="待定义" detail="终端动销、门店覆盖和线路数据" tone="warn" /></div>}</Workspace>; }
const PAGE_SIZE = 50;

function BusinessDataWorkspace({ dealers }: { dealers: string[] }) {
  const [tab, setTab] = useState<(typeof businessObjects)[number]['key']>('orders');
  const [query, setQuery] = useState('');
  const [dealer, setDealer] = useState('全部经销商');
  const [page, setPage] = useState(0);
  const [data, setData] = useState<BusinessResponse | null>(null);
  const [selectedRow, setSelectedRow] = useState<BusinessRow | null>(null);
  const [orderDetail, setOrderDetail] = useState<OrderDetail | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const current = businessObjects.find((item) => item.key === tab) ?? businessObjects[0];
  const apiBase = ec101Api();
  const changeTab = (value: (typeof businessObjects)[number]['key']) => { setTab(value); setPage(0); };
  const changeQuery = (value: string) => { setQuery(value); setPage(0); };
  const changeDealer = (value: string) => { setDealer(value); setPage(0); };
  useEffect(() => {
    const controller = new AbortController();
    const params = new URLSearchParams({ limit: String(PAGE_SIZE), offset: String(page * PAGE_SIZE) });
    if (query.trim()) params.set('q', query.trim());
    if (dealer !== '全部经销商') params.set('dealer', dealer);
    fetch(`${apiBase}/api/business-data/${tab}?${params.toString()}`, { signal: controller.signal })
      .then((response) => { if (!response.ok) throw new Error(`HTTP ${response.status}`); return response.json() as Promise<BusinessResponse>; })
      .then((nextData) => { setData(nextData); setError(''); setSelectedRow(null); setOrderDetail(null); setLoading(false); })
      .catch((reason: Error) => { if (reason.name !== 'AbortError') { setData(null); setError('数据服务不可用，请先启动本地 API（python3 api/server.py）。'); setLoading(false); } })
      .finally(() => setLoading(false));
    return () => controller.abort();
  }, [apiBase, dealer, page, query, tab]);
  const openRow = (row: BusinessRow) => {
    setSelectedRow(row); setOrderDetail(null);
    if (tab !== 'orders') return;
    fetch(`${apiBase}/api/business-data/orders/${row.id}`).then((response) => (response.ok ? (response.json() as Promise<OrderDetail>) : null)).then((detail) => setOrderDetail(detail)).catch(() => setOrderDetail(null));
  };
  const totalPages = Math.max(1, Math.ceil((data?.total ?? 0) / PAGE_SIZE));
  const exportCsv = () => {
    const rows = data?.rows ?? [];
    const escape = (value: unknown) => {
      const normalized = value === null || value === undefined ? '' : typeof value === 'object' ? JSON.stringify(value) : value;
      const text = typeof normalized === 'number' ? normalized.toString() : typeof normalized === 'string' ? normalized : '';
      return `"${text.replaceAll('"', '""')}"`;
    };
    const csv = '\uFEFF' + [current.columns.map((column) => column[1]), ...rows.map((row) => current.columns.map(([key]) => row[key]))].map((row) => row.map(escape).join(',')).join('\n');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8;' }));
    const link = document.createElement('a');
    link.href = url;
    link.download = `EC101-业务数据-${current.label}-${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
    URL.revokeObjectURL(url);
  };
  const rows = data?.rows ?? [];
  return <Workspace title="业务数据" subtitle="查询 SQLite 中已导入的真实业务事实；只读展示，可查看标准数据与 CORE 对象，并导出当前筛选结果"><div className="mb-5 flex flex-wrap gap-2 border-b border-slate-100 pb-4">{businessObjects.map((item) => <button className={`rounded-lg px-3 py-2 text-xs font-medium transition ${tab === item.key ? 'bg-[#0f766e] text-white' : 'bg-slate-50 text-slate-600 hover:bg-slate-100'}`} key={item.key} onClick={() => changeTab(item.key)} type="button">{item.label}</button>)}</div><div className="mb-4 flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div className="flex flex-1 flex-wrap items-center gap-2"><div className="relative min-w-[220px] flex-1"><Search className="absolute left-3 top-2.5 text-slate-400" size={15} /><input aria-label="搜索业务数据" className="w-full rounded-lg border border-slate-200 py-2 pl-9 pr-3 text-sm outline-none focus:ring-2 focus:ring-[#0f766e]" onChange={(event) => changeQuery(event.target.value)} placeholder={`搜索${current.label}...`} value={query} /></div><select aria-label="筛选经销商" className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm text-slate-700 outline-none focus:ring-2 focus:ring-[#0f766e]" onChange={(event) => changeDealer(event.target.value)} value={dealer}><option>全部经销商</option>{dealers.map((name) => <option key={name}>{name}</option>)}</select></div><button className="inline-flex items-center justify-center gap-2 rounded-lg border border-[#b9dcd7] bg-[#f0fbf8] px-3 py-2 text-xs font-semibold text-[#0f766e] hover:bg-[#e3f6f1]" disabled={!data || loading} onClick={exportCsv} type="button"><Download size={15} />导出当前页</button></div>{loading ? <div className="rounded-xl border border-slate-200 bg-slate-50 p-8 text-center text-sm text-slate-500">正在从标准库读取……</div> : error ? <div className="rounded-xl border border-amber-200 bg-amber-50 p-5 text-sm text-amber-800">{error}</div> : <><div className="mb-3 flex flex-wrap items-center justify-between gap-2 text-xs text-slate-500"><span>{current.label} · 共 {data?.total ?? 0} 行 · 第 {page + 1} / {totalPages} 页</span><span className="flex items-center gap-2"><button className="rounded-lg border border-slate-200 px-2 py-1 font-medium text-slate-600 disabled:opacity-40" disabled={page === 0} onClick={() => setPage((value) => Math.max(0, value - 1))} type="button">上一页</button><button className="rounded-lg border border-slate-200 px-2 py-1 font-medium text-slate-600 disabled:opacity-40" disabled={page + 1 >= totalPages} onClick={() => setPage((value) => value + 1)} type="button">下一页</button></span></div>{rows.length ? <Table headers={[...current.columns.map((column) => column[1]), '操作']} rows={rows.map((row) => [...current.columns.map(([key]) => String(row[key] ?? '—')), <button className="text-xs font-semibold text-[#0f766e]" key="detail" onClick={() => openRow(row)} type="button">查看详情</button>])} /> : <div className="rounded-xl border border-slate-200 p-8 text-center text-sm text-slate-500">{dealers.length ? '没有匹配的数据' : '标准库还没有数据，请先在“数据接入”上传标准数据'}</div>}{selectedRow ? <div className="mt-5 rounded-xl border border-teal-100 bg-teal-50/50 p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-semibold tracking-[0.12em] text-[#328075]">业务数据详情</p><p className="mt-1 text-sm font-semibold text-slate-900">{current.label} · {String(selectedRow[current.columns[0][0]] ?? '')}</p></div><button className="text-xs font-semibold text-slate-500" onClick={() => { setSelectedRow(null); setOrderDetail(null); }} type="button">关闭</button></div><div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{current.columns.map(([key, label]) => <div className="rounded-lg border border-teal-100 bg-white/80 p-3" key={key}><p className="text-[11px] text-slate-500">{label}</p><p className="mt-1 text-xs font-semibold text-slate-800">{String(selectedRow[key] ?? '—')}</p></div>)}</div>{orderDetail ? <OrderDetailPanel detail={orderDetail} /> : null}</div> : null}</>}<p className="mt-4 text-[11px] leading-5 text-slate-400">数据来自标准导入库 `mvp/ec101_standard.db` 的当前有效批次；“订单优惠(全部)”是平台所有促销（含非可乐活动和券）的合计，仅用于对照，费用只按核销明细统计。</p></Workspace>;
}
function OrderDetailPanel({ detail }: { detail: OrderDetail }) {
  const lines = detail.lines ?? []; const executions = detail.activity_executions ?? []; const coupons = detail.coupon_redemptions ?? []; const release = detail.release ?? null; const entitlement = detail.entitlement ?? null;
  return <div className="mt-4 space-y-4">
    <div className="rounded-lg border border-teal-100 bg-white/80 p-3"><p className="text-xs font-semibold text-slate-700">费用核算（只按核销明细）</p>{release ? <div className="mt-2 flex flex-wrap items-center gap-3 text-xs"><Status status={release.is_candidate ? '可提交' : '待确认'} /><span>{String(release.reason ?? '')}</span><span>活动优惠 {money(release.activity_benefit as number)}</span><span>券优惠 {money(release.coupon_benefit as number)}</span><span className="text-slate-500">核算日 {String(release.calc_date ?? '')} · 截止 {String(release.release_cutoff ?? '')}</span></div> : <p className="mt-2 text-xs text-slate-500">该订单未参与任何可乐活动或优惠券核销，不计费用。</p>}</div>
    {entitlement ? <div className="rounded-lg border border-teal-100 bg-white/80 p-3"><p className="text-xs font-semibold text-slate-700">规则核对（promotion_calculator，不计费）</p><div className="mt-2 flex flex-wrap items-center gap-3 text-xs"><span>一致性 {String(entitlement.consistency ?? '按核销明细')}</span><span>理论活动 {entitlement.theoretical_activity_benefit == null ? '—' : money(entitlement.theoretical_activity_benefit as number)}</span><span>理论券 {entitlement.theoretical_coupon_benefit == null ? '—' : money(entitlement.theoretical_coupon_benefit as number)}</span>{entitlement.gift_qty_entitled != null ? <span>应赠 {String(entitlement.gift_qty_entitled)} / 实赠 {String(entitlement.gift_qty_actual ?? '—')}</span> : null}<span className="text-slate-500">{String(entitlement.formula_ref ?? '')}</span></div></div> : null}
    {executions.length ? <Table headers={['活动编号', '活动名称', '类型', '活动商品金额', '活动优惠']} rows={executions.map((row) => [String(row.activity_no ?? ''), String(row.activity_name ?? ''), String(row.activity_type ?? ''), money(row.product_amount as number), money(row.discount_amount as number)])} /> : null}
    {coupons.length ? <Table headers={['券编号', '券状态', '使用时间', '券优惠']} rows={coupons.map((row) => [String(row.coupon_no ?? ''), String(row.status ?? ''), String(row.used_at ?? ''), money(row.discount_amount as number)])} /> : null}
    <div><p className="mb-2 text-xs font-semibold text-slate-700">订单商品行（{lines.length} 行）</p><Table headers={['商品编号', '商品', '规格', '数量', '单位', '单价', '折前金额', '优惠金额', '实付金额', '活动编号', '优惠券编号']} rows={lines.map((row) => [String(row.product_no ?? ''), String(row.product_name ?? ''), String(row.spec ?? ''), String(row.quantity ?? ''), String(row.unit ?? ''), String(row.unit_price ?? ''), String(row.pre_discount_amount ?? ''), String(row.discount_amount ?? ''), String(row.paid_amount ?? ''), String(row.activity_numbers ?? ''), String(row.coupon_numbers ?? '')])} /></div>
  </div>;
}
function Workspace({ title, subtitle, children }: { title: string; subtitle: string; children: React.ReactNode }) { return <section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="mb-5"><p className="text-lg font-semibold text-slate-900">{title}</p><p className="mt-1 text-xs leading-5 text-slate-500">{subtitle}</p></div>{children}</section>; }
function Filter({ dealer, dealers, setDealer, action }: { dealer: string; dealers: string[]; setDealer: (value: string) => void; action?: ReactNode }) { return <div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2 text-xs text-slate-500"><SlidersHorizontal size={15} /> 当前显示 {dealer}</div><div className="flex flex-wrap items-center gap-3">{action}<select aria-label="选择经销商" className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm text-slate-700 outline-none focus:ring-2 focus:ring-[#0f766e]" onChange={(event) => setDealer(event.target.value)} value={dealer}><option>全部经销商</option>{dealers.map((name) => <option key={name}>{name}</option>)}</select></div></div>; }
function Table({ headers, rows }: { headers: string[]; rows: React.ReactNode[][] }) { return <div className="overflow-x-auto rounded-xl border border-slate-200"><table className="min-w-full text-left text-sm"><thead className="bg-slate-50 text-xs font-medium text-slate-500"><tr>{headers.map((header) => <th className="whitespace-nowrap px-4 py-3 first:pl-5 last:pr-5" key={header}>{header}</th>)}</tr></thead><tbody className="divide-y divide-slate-100">{rows.map((row, index) => <tr className="transition hover:bg-slate-50" key={index}>{row.map((cell, cellIndex) => <td className="px-4 py-4 align-top first:pl-5 last:pr-5" key={cellIndex}>{cell}</td>)}</tr>)}</tbody></table></div>; }
function Status({ status }: { status: Status }) { return <span className={`inline-flex whitespace-nowrap rounded-full px-2.5 py-1 text-xs font-medium ring-1 ring-inset ${statusStyles[status]}`}>{status}</span>; }
function PanelHeader({ title, subtitle, action, onClick }: { title: string; subtitle: string; action?: string; onClick?: () => void }) { return <div className="flex flex-col gap-2 border-b border-slate-100 px-5 py-4 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="font-semibold text-slate-900">{title}</h2><p className="mt-1 text-xs text-slate-500">{subtitle}</p></div>{action && onClick ? <button className="text-xs font-semibold text-[#0f766e]" onClick={onClick} type="button">{action} →</button> : null}</div>; }
function Metric({ label, value, note, tone }: { label: string; value: string; note: string; tone: 'emerald' | 'sky' | 'teal' | 'amber' }) { const colors = { emerald: 'border-emerald-100 bg-emerald-50/70 text-emerald-700', sky: 'border-sky-100 bg-sky-50/70 text-sky-700', teal: 'border-teal-100 bg-teal-50/70 text-teal-700', amber: 'border-amber-100 bg-amber-50/70 text-amber-700' }; return <article className={`rounded-2xl border p-4 ${colors[tone]}`}><p className="text-xs font-medium opacity-80">{label}</p><p className="mt-2 text-2xl font-semibold tracking-tight">{value}</p><p className="mt-2 text-xs opacity-75">{note}</p></article>; }
function Health({ label, value, good = false }: { label: string; value: string; good?: boolean }) { return <div className="flex items-center justify-between rounded-lg bg-slate-50 px-3 py-2.5"><span className="text-xs text-slate-600">{label}</span><span className={`text-xs font-semibold ${good ? 'text-emerald-700' : 'text-amber-700'}`}>{value}</span></div>; }
function Feature({ title, text }: { title: string; text: string }) { return <article className="rounded-xl border border-slate-200 bg-white p-4"><div className="grid h-8 w-8 place-items-center rounded-lg bg-teal-50 text-teal-700"><PackageCheck size={18} /></div><h3 className="mt-3 text-sm font-semibold text-slate-800">{title}</h3><p className="mt-1 text-xs leading-5 text-slate-500">{text}</p></article>; }
function Mapping({ title, value, detail, tone }: { title: string; value: string; detail: string; tone: 'good' | 'warn' | 'neutral' }) { return <article className="rounded-xl border border-slate-200 p-4"><p className="text-xs text-slate-500">{title}</p><p className={`mt-2 text-xl font-semibold ${tone === 'good' ? 'text-emerald-700' : tone === 'warn' ? 'text-amber-700' : 'text-slate-800'}`}>{value}</p><p className="mt-1 text-xs leading-5 text-slate-500">{detail}</p></article>; }
function Quality({ title, value, detail, tone }: { title: string; value: string; detail: string; tone: 'good' | 'warn' | 'bad' }) { return <article className="rounded-xl border border-slate-200 p-4"><p className="text-xs text-slate-500">{title}</p><p className={`mt-2 text-2xl font-semibold ${tone === 'good' ? 'text-emerald-700' : tone === 'warn' ? 'text-amber-700' : 'text-rose-700'}`}>{value}</p><p className="mt-1 text-xs text-slate-500">{detail}</p></article>; }
function Info({ text }: { text: string }) { return <div className="mt-5 rounded-xl border border-slate-200 bg-slate-50 p-4 text-xs leading-5 text-slate-600">{text}</div>; }
function EvidencePanel({ row, close }: { row: ActivityRow; close: () => void }) { return <div className="fixed inset-0 z-20 flex items-end justify-end bg-slate-950/20 p-4 sm:items-center"><section className="max-h-[90vh] w-full max-w-xl overflow-y-auto rounded-2xl border border-slate-200 bg-white p-5 shadow-2xl"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-semibold tracking-[0.12em] text-[#328075]">证据链详情</p><h2 className="mt-1 text-lg font-semibold text-slate-900">{row.activity}</h2><p className="mt-1 text-xs text-slate-500">{row.dealer} · {row.platform}</p><div className="mt-3"><ReportLink href={row.reportHref} /></div></div><button className="text-xs font-semibold text-slate-500" onClick={close} type="button">关闭</button></div><div className="mt-5 grid gap-3 sm:grid-cols-2">{[['核算结果', row.result], ['权益类型', row.kind], ['核算口径', row.rule], ['核算批次', row.batch], ['活动来源', '标准活动（从活动明细解析）'], ['费用依据', '标准活动核销明细']].map(([label, value]) => <div className="rounded-lg border border-slate-200 bg-slate-50 p-3" key={label}><p className="text-[11px] text-slate-500">{label}</p><p className="mt-1 text-xs font-semibold text-slate-800">{value}</p></div>)}</div><div className="mt-5 rounded-xl border border-slate-200 bg-slate-50 p-4"><p className="text-xs font-semibold text-slate-700">当前结论</p><p className="mt-1 text-xs leading-5 text-slate-500">{row.detail}。结果来自已保存的计算批次，页面只负责展示和确认，不修改核算公式。</p></div></section></div>; }
function DraftPanel({ rows, close }: { rows: FeeTpmSettlementRow[]; close: () => void }) { const total = rows.reduce((sum, row) => sum + Number(row.settleAmount ?? 0), 0); const orders = rows.reduce((sum, row) => sum + row.releasedOrders, 0); const dealers = Array.from(new Set(rows.map((row) => row.dealer))); return <div className="fixed inset-0 z-20 flex items-end justify-end bg-slate-950/20 p-4 sm:items-center"><section className="w-full max-w-lg rounded-2xl border border-slate-200 bg-white p-5 shadow-2xl"><div className="flex items-start justify-between"><div><p className="text-xs font-semibold tracking-[0.12em] text-[#328075]">结算草稿</p><h2 className="mt-1 text-lg font-semibold text-slate-900">{dealers.length ? dealers.join('、') : '暂无可释放活动'}</h2></div><button className="text-xs font-semibold text-slate-500" onClick={close} type="button">关闭</button></div><div className="mt-5 rounded-xl border border-emerald-100 bg-emerald-50/60 p-4"><p className="text-xs text-emerald-800">可释放金额（金额活动）</p><p className="mt-1 text-2xl font-semibold text-emerald-900">{money(total)}</p><p className="mt-1 text-xs text-emerald-800">{orders} 单可释放 · {rows.length} 个活动</p></div><div className="mt-4 space-y-2 text-xs text-slate-600">{rows.map((row) => <p key={row.activityId}>{row.activityName}：{money(row.settleAmount)} · {row.releasedOrders} 单 · 核算日 {row.calcDate}</p>)}<p>后续动作：业务确认 → 财务确认 → 上账（本期只生成草稿，不写回数据库）</p></div><button className="mt-5 w-full rounded-xl bg-slate-900 px-4 py-2.5 text-sm font-semibold text-white" onClick={close} type="button">关闭草稿</button></section></div>; }
